"""Random arrays to sort.

Values stay small and the arrays stay short, because what is being tested is
the loop, not the machine. The shapes that break a half-written insertion sort
-- reversed input, heavy duplication, one element out of place -- each get a
builder rather than being left to a uniform shuffle.
"""


def generate(rng, count):
    builders = (_shuffled, _reversed, _many_duplicates, _nearly_sorted)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, description=""):
    return {
        "name": name,
        "stdin": "%d\n%s\n" % (len(values), " ".join(str(v) for v in values)),
        "description": description,
    }


def _shuffled(rng, index):
    values = [rng.randint(-99, 99) for _ in range(rng.randint(6, 12))]
    return _case("shuffled values #%d" % index, values)


def _reversed(rng, index):
    values = sorted((rng.randint(-99, 99) for _ in range(rng.randint(5, 10))),
                    reverse=True)
    return _case("in reverse order #%d" % index, values,
                 "The worst case for insertion sort: every element travels the "
                 "whole way back.")


def _many_duplicates(rng, index):
    pool = [rng.randint(-20, 20) for _ in range(3)]
    values = [rng.choice(pool) for _ in range(rng.randint(6, 12))]
    return _case("only a few distinct values #%d" % index, values,
                 "Mostly repeats, drawn from three values.")


def _nearly_sorted(rng, index):
    values = sorted(rng.randint(-99, 99) for _ in range(rng.randint(6, 11)))
    first = rng.randrange(len(values) - 1)
    second = rng.randrange(first + 1, len(values))
    values[first], values[second] = values[second], values[first]
    return _case("one pair out of place #%d" % index, values,
                 "Sorted apart from a single swapped pair.")
